        display: grid;
        grid-template-rows: auto 1fr;
        overflow: hidden;
      }

      #main {
        display: grid;
        grid-template-rows: auto auto 1fr;
        overflow: auto;
        padding: 0;
      }

      /* Adapt the grid to public views (no filters or watchers sections) */
      &.public #main {
        grid-template-rows: 1fr;
      }
    }
